const notas = [7.5, 8, 6.5, 9];
let soma = 0;

for (const nota of notas) {
  soma = soma + nota;
}

const media = soma / notas.length;

if (media >= 7) {
  console.log('Aprovado com média', media);
} else {
  console.log('Recuperação com média', media);
}

const botao = document.querySelector('#botao-inscricao');
const aviso = document.querySelector('#contador');
let inscritos = 0;

botao.addEventListener('click', () => {
  inscritos = inscritos + 1;
  aviso.textContent = 'Inscritos: ' + inscritos;
  aviso.classList.add('destaque');
});

